import{_ as t,o as a,c as i,aA as s}from"./chunks/framework.BBHDtxxT.js";const g=JSON.parse('{"title":"FAQ / Gotchas","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":null}'),n={name:"faq.md"};function o(r,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="FAQ-/-Gotchas" tabindex="-1">FAQ / Gotchas <a class="header-anchor" href="#FAQ-/-Gotchas" aria-label="Permalink to &quot;FAQ / Gotchas {#FAQ-/-Gotchas}&quot;">​</a></h1><p>Common surprises and how to handle them.</p><h2 id="Aliases-for-clashing-names" tabindex="-1">Aliases for clashing names <a class="header-anchor" href="#Aliases-for-clashing-names" aria-label="Permalink to &quot;Aliases for clashing names {#Aliases-for-clashing-names}&quot;">​</a></h2><p>A few exports have aliases so you can avoid clashes with locals (especially when working inside HTMXObjects structs that often have a <code>data</code> field or a <code>draw</code> method already in scope):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Canonical</th><th style="text-align:right;">Alias</th><th style="text-align:right;">When to reach for the alias</th></tr></thead><tbody><tr><td style="text-align:right;"><code>data</code></td><td style="text-align:right;"><code>vdata</code></td><td style="text-align:right;">Your struct/closure has a field named <code>data</code></td></tr><tr><td style="text-align:right;"><code>draw</code></td><td style="text-align:right;"><code>vdraw</code></td><td style="text-align:right;"><code>draw</code> is also exported by AlgebraOfGraphics or shadowed in your scope</td></tr><tr><td style="text-align:right;"><code>vlspec</code></td><td style="text-align:right;">—</td><td style="text-align:right;">Use to construct a raw Vega-Lite spec wrapper directly (no AoG needed)</td></tr></tbody></table><p>Both aliases call straight through to the canonical implementation — no behavioural difference.</p><h2 id="Legend-binding-limitation" tabindex="-1">Legend binding limitation <a class="header-anchor" href="#Legend-binding-limitation" aria-label="Permalink to &quot;Legend binding limitation {#Legend-binding-limitation}&quot;">​</a></h2><p>Vega-Lite supports binding legend selections to a parameter (so clicking a legend entry filters the visible marks). AlgebraOfVega wires this up automatically when there&#39;s exactly <strong>one</strong> non-position channel (e.g. just <code>color</code>). With <strong>two or more</strong> non-position channels (e.g. <code>color=:a, linestyle=:b</code>), legend binding is currently <strong>not</strong> generated — you&#39;ll see a warning and you&#39;ll need to filter via a custom Vega-Lite param.</p><h2 id="Faceting-select-interactions" tabindex="-1">Faceting + <code>select=</code> interactions <a class="header-anchor" href="#Faceting-select-interactions" aria-label="Permalink to &quot;Faceting + `select=` interactions {#Faceting-select-interactions}&quot;">​</a></h2><p><code>config(select=:origin)</code> adds a client-side dropdown that filters the data frame <em>before</em> it reaches any layer. When you also use faceting (<code>row=</code> / <code>col=</code> channels), the filter applies to <em>all</em> facets — there&#39;s no per-facet dropdown. If you want per-facet interaction, use <code>mapping_controls</code> + <code>auto_remap_node</code> instead.</p><h2 id="Deep-merged-encoding" tabindex="-1">Deep-merged encoding <a class="header-anchor" href="#Deep-merged-encoding" aria-label="Permalink to &quot;Deep-merged encoding {#Deep-merged-encoding}&quot;">​</a></h2><p>When you pass <code>config(encoding = (; x = (; scale = (; type = &quot;log&quot;))))</code>, AoV <strong>deep-merges</strong> that into the encoding dict it generated from <code>mapping(...)</code>. So you can override (or add to) any auto-generated channel without re-specifying it from scratch:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(df) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> mapping</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:y</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> visual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Scatter) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(encoding </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (; scale </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (; type </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;log&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)),</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tooltip </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [(; field</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), (; field</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:y</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), (; field</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)],   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># extra tooltip fields</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>If the override doesn&#39;t take effect, the most likely cause is a typo in a channel name or a Symbol-vs-String mismatch — the merge is exact.</p><h2 id="When-to-use-pregrouped" tabindex="-1">When to use <code>pregrouped()</code> <a class="header-anchor" href="#When-to-use-pregrouped" aria-label="Permalink to &quot;When to use `pregrouped()` {#When-to-use-pregrouped}&quot;">​</a></h2><p>AoG&#39;s <code>pregrouped(xs, ys, ...)</code> is the right hook when your data is already in nested-vector shape (one element per group). AoV passes through to AoG&#39;s own grouping behaviour. Use it when you have e.g. a <code>Vector{Vector{Float64}}</code> of curves and don&#39;t want to flatten + tag with a group column first.</p><h2 id="lineribbon-vs-ribbon-vs-precomputed-bands" tabindex="-1"><code>lineribbon</code> vs <code>ribbon</code> vs precomputed bands <a class="header-anchor" href="#lineribbon-vs-ribbon-vs-precomputed-bands" aria-label="Permalink to &quot;`lineribbon` vs `ribbon` vs precomputed bands {#lineribbon-vs-ribbon-vs-precomputed-bands}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">You have</th><th style="text-align:right;">Use</th></tr></thead><tbody><tr><td style="text-align:right;">Long-format draws (one row per draw × x)</td><td style="text-align:right;"><code>lineribbon</code> — computes intervals from draws</td></tr><tr><td style="text-align:right;">Long-format draws + you want only the band (no centre line)</td><td style="text-align:right;"><code>ribbon</code></td></tr><tr><td style="text-align:right;">Precomputed <code>(lo, mid, hi)</code> columns</td><td style="text-align:right;"><code>lineribbon(...; bands = [(0.5, :lo50, :hi50), (0.95, :lo95, :hi95)])</code> (or <code>ribbon(...; bands=…)</code>) — skips the draw-based estimator</td></tr></tbody></table><p>See <a href="./uncertainty">Uncertainty Visualisation</a> for full examples.</p><h2 id="CDN-versions" tabindex="-1">CDN versions <a class="header-anchor" href="#CDN-versions" aria-label="Permalink to &quot;CDN versions {#CDN-versions}&quot;">​</a></h2><p><code>vega_head()</code> injects CDN tags pinned to the versions in <code>vega_cdn_urls()</code>. If you want to vendor Vega locally or pin specific versions, override <code>vega_cdn_urls()</code> (it returns a <code>NamedTuple</code> with <code>vega</code>, <code>vegalite</code>, <code>embed</code> fields) and AoV will inject your URLs instead.</p><h2 id="My-spec-doesn&#39;t-render-and-I-get-no-error" tabindex="-1">&quot;My spec doesn&#39;t render and I get no error&quot; <a class="header-anchor" href="#My-spec-doesn&#39;t-render-and-I-get-no-error" aria-label="Permalink to &quot;&amp;quot;My spec doesn&amp;#39;t render and I get no error&amp;quot; {#&quot;My-spec-doesn&#39;t-render-and-I-get-no-error&quot;}&quot;">​</a></h2><p>Vega-Lite is forgiving — it&#39;ll silently render a blank chart for a malformed spec. Two debugging moves:</p><ol><li><p><strong><code>println(to_json(spec))</code></strong> — inspect the actual Vega-Lite JSON being emitted.</p></li><li><p>Open browser DevTools, paste the JSON into the <a href="https://vega.github.io/editor/#/edited" target="_blank" rel="noreferrer">Vega Editor</a> — it produces actionable errors in a way the embed runtime doesn&#39;t.</p></li></ol><h2 id="HTMX-update_data-doesn&#39;t-refresh" tabindex="-1">HTMX + <code>update_data</code> doesn&#39;t refresh <a class="header-anchor" href="#HTMX-update_data-doesn&#39;t-refresh" aria-label="Permalink to &quot;HTMX + `update_data` doesn&amp;#39;t refresh {#HTMX-update_data-doesn&#39;t-refresh}&quot;">​</a></h2><p><code>update_data(id, new_rows)</code> works only when the rendered spec was given the same <code>id</code> (set via <code>config(id=...)</code>). If you don&#39;t set an explicit <code>id</code>, AoV assigns a hash-derived one — but the update handler can&#39;t guess it. In a dashboard, always set <code>config(id=&quot;my-plot-1&quot;)</code> for any spec you intend to update from a server endpoint.</p>',26)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
